│   │   ├── App.tsx
│   │   ├── components/
│   │   │   ├── Carousel.tsx
│   │   │   ├── TurnCard.tsx
│   │   │   └── InputBox.tsx
│   │   └── hooks/
│   │       └── useChat.ts    # SSE streaming hook
