+import type { Request, Response } from "express";
+import type { TurnstileConfig } from "./config.js";
+
+interface StubTurn {
+  id: string;
+  index: number;
+  user: string;
+  assistant: string;
+  timestamp: string;
+  metadata?: Record<string, unknown>;
+}
+
+interface StubSession {
+  id: string;
+  status: "active" | "closed";
+  createdAt: string;
+  updatedAt: string;
+  metadata: Record<string, unknown>;
+  turns: StubTurn[];
+  distillation: null;
+}
+
+const sessions = new Map<string, StubSession>();
+
+function isoDate() {
+  return new Date().toISOString();
+}
+
+function seedTurns(): StubTurn[] {
+  const now = Date.now();
+  return [
+    {
+      id: "turn_001",
+      index: 0,
+      user: "What is Software-Defined Business?",
+      assistant:
+        "Software-Defined Business (SDB) treats operating models like code. " +
+        "Turnstile is currently running in stub mode, so this answer is a canned example.",
+      timestamp: new Date(now - 60_000).toISOString(),
+      metadata: {
+        docs_in_context: ["whitepapers/sdb-framework/overview.md"],
+        token_count: 1200
+      }
+    },
+    {
+      id: "turn_002",
+      index: 1,
+      user: "How do personas influence the prompt?",
+      assistant:
+        "Personas contribute structured system prompts supplied by the Orchestrator. " +
+        "In stub mode we simply display this placeholder response.",
+      timestamp: new Date(now - 30_000).toISOString(),
+      metadata: {
+        docs_in_context: ["whitepapers/sdb-framework/persona.md"],
+        token_count: 800
+      }
+    }
+  ];
+}
+
+function createSession(metadata: Record<string, unknown> | undefined): StubSession {
+  const id = `sess_${crypto.randomUUID().slice(0, 8)}`;
+  const createdAt = isoDate();
+  const session: StubSession = {
+    id,
+    status: "active",
+    createdAt,
+    updatedAt: createdAt,
+    metadata: metadata ?? { source: "turnstile-stub" },
+    turns: seedTurns(),
+    distillation: null
+  };
+  sessions.set(id, session);
+  return session;
+}
+
+function getSession(id: string): StubSession | undefined {
+  return sessions.get(id);
+}
+
+function appendTurn(session: StubSession, user: string, assistant: string) {
+  const turn: StubTurn = {
+    id: `turn_${String(session.turns.length + 1).padStart(3, "0")}`,
+    index: session.turns.length,
+    user,
+    assistant,
+    timestamp: isoDate(),
+    metadata: {
+      docs_in_context: ["whitepapers/demo-context.md"],
+      token_count: assistant.length / 4
+    }
+  };
+  session.turns.push(turn);
+  session.updatedAt = isoDate();
+}
+
+function serializeSession(session: StubSession) {
+  return {
+    session_id: session.id,
+    status: session.status,
+    turns: session.turns,
+    distillation: session.distillation,
+    metadata: session.metadata,
+    created_at: session.createdAt,
+    updated_at: session.updatedAt
+  };
+}
+
+function sendEvent(res: Response, event: string, data: Record<string, unknown>) {
+  res.write(`event: ${event}\n`);
+  res.write(`data: ${JSON.stringify(data)}\n\n`);
+}
+
+function chunkResponse(text: string, chunkSize = 60): string[] {
+  const chunks: string[] = [];
+  let current = "";
+  for (const char of text) {
+    current += char;
+    if (current.length >= chunkSize && char === " ") {
+      chunks.push(current);
+      current = "";
+    }
+  }
+  if (current) {
+    chunks.push(current);
+  }
+  return chunks;
+}
+
+function synthesizeResponse(message: string, session: StubSession): string {
+  const turnCount = session.turns.length;
+  return [
+    `You asked: "${message}".`,
+    "This is a stubbed response so you can explore Turnstile without the full stack.",
+    `Session currently contains ${turnCount} prior turns.`,
+    "Once Orchestrator is wired in, this stream will carry the real LLM output."
+  ].join("\n\n");
+}
+
+export function createStubHandlers(cfg: TurnstileConfig) {
+  const latency = cfg.stubLatencyMs;
+
+  const chat = async (req: Request, res: Response) => {
+    const { message, session_id: sessionId } = req.body ?? {};
+    if (!message || !sessionId) {
+      res.status(400).json({
+        error: {
+          code: "validation_error",
+          message: "message and session_id are required in stub mode"
+        }
+      });
+      return;
+    }
+
+    const session = getSession(sessionId);
+    if (!session) {
+      res.status(404).json({
+        error: { code: "session_not_found", message: `Unknown session ${sessionId}` }
+      });
+      return;
+    }
+
+    res.status(200);
+    res.setHeader("Content-Type", "text/event-stream");
+    res.setHeader("Cache-Control", "no-cache");
+    res.setHeader("Connection", "keep-alive");
+
+    const response = synthesizeResponse(message, session);
+    const chunks = chunkResponse(response);
+    let cancelled = false;
+
+    req.on("close", () => {
+      cancelled = true;
+    });
+
+    const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
+
+    const run = async () => {
+      const steps = [
+        { id: "session", status: "complete" },
+        { id: "docs", status: "complete", artifacts: 3 },
+        { id: "persona", status: "complete" }
+      ];
+
+      for (const step of steps) {
+        if (cancelled) return;
+        sendEvent(res, "step", step);
+        await sleep(latency);
+      }
+
+      for (const chunk of chunks) {
+        if (cancelled) return;
+        sendEvent(res, "chunk", { content: chunk });
+        await sleep(latency);
+      }
+
+      if (!cancelled) {
+        appendTurn(session, message, response);
+        sendEvent(res, "done", {
+          turn_id: session.turns[session.turns.length - 1].id,
+          total_tokens: Math.round(response.length / 4)
+        });
+        res.end();
+      }
+    };
+
+    run().catch((err) => {
+      console.error("Stub stream failure", err);
+      if (!res.headersSent) {
+        res.status(500);
+      }
+      sendEvent(res, "error", { code: "stub_failure", message: "Stub stream failed." });
+      res.end();
+    });
+  };
+
+  const createSessionHandler = (req: Request, res: Response) => {
+    const session = createSession(req.body?.metadata);
+    res.status(201).json({
+      session_id: session.id,
+      status: session.status,
+      created_at: session.createdAt
+    });
+  };
+
+  const getSessionHandler = (req: Request, res: Response) => {
+    const session = getSession(req.params.id);
+    if (!session) {
+      res.status(404).json({
+        error: { code: "session_not_found", message: `Unknown session ${req.params.id}` }
+      });
+      return;
+    }
+    res.json(serializeSession(session));
+  };
+
+  const health = (_req: Request, res: Response) => {
+    res.json({
+      status: "stub",
+      mode: "stub",
+      stub_sessions: sessions.size
+    });
+  };
+
+  return { chat, createSession: createSessionHandler, getSession: getSessionHandler, health };
+}
